title: Weigh a cart from the catalog
description:
Adds `cartGrams(cart)`, for shipping.

--- src/catalog.js (modified, +5 −0)
@@ -1,3 +1,8 @@
 import { readFileSync } from "node:fs";
 export const CATALOG = JSON.parse(readFileSync(new URL("./catalog.json", import.meta.url), "utf8"));
 export const findSku = (sku) => CATALOG.find((i) => i.sku === String(sku).toLowerCase()) ?? null;
+
+// Total weight of a cart whose skus are in the catalog; unknown skus weigh nothing.
+export function cartGrams(cart) {
+  return cart.lines.reduce((g, l) => g + (findSku(l.sku)?.grams ?? 0) * l.quantity, 0);
+}

